def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = max(set(value for row in grid for value in row), key=lambda value: sum(row.count(value) for row in grid))
    points = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color != background:
                points.setdefault(color, []).append((r, c))

    # Join same-colored diagonal endpoints, leaving any existing markers intact.
    for color in sorted(points, reverse=True):
        pts = points[color]
        for i, (r1, c1) in enumerate(pts):
            for r2, c2 in pts[i + 1:]:
                dr, dc = r2 - r1, c2 - c1
                if abs(dr) == abs(dc) and dr != 0:
                    sr, sc = (1 if dr > 0 else -1), (1 if dc > 0 else -1)
                    r, c = r1, c1
                    while (r, c) != (r2, c2):
                        if grid[r][c] == background:
                            out[r][c] = color
                        r += sr
                        c += sc
                    if grid[r2][c2] == background:
                        out[r2][c2] = color

    # At a crossing, extend the differently colored diagonal through its marker.
    for color, pts in points.items():
        for r0, c0 in pts:
            crossing_slope = None
            for other, other_pts in points.items():
                if other == color:
                    continue
                for i, (r1, c1) in enumerate(other_pts):
                    for r2, c2 in other_pts[i + 1:]:
                        dr0, dc0 = r2-r1, c2-c1
                        if abs(dr0) != abs(dc0) or dr0 == 0:
                            continue
                        if abs(r0-r1) == abs(c0-c1) and (r0-r1)*(r2-r1) >= 0 and (c0-c1)*(c2-c1) >= 0:
                            if min(r1,r2) <= r0 <= max(r1,r2) and min(c1,c2) <= c0 <= max(c1,c2):
                                crossing_slope = 1 if dr0 * dc0 > 0 else -1
            if crossing_slope is not None:
                dr, dc = 1, -crossing_slope
                rr, cc = r0, c0
                while 0 <= rr-dr < h and 0 <= cc-dc < w:
                    rr -= dr
                    cc -= dc
                while 0 <= rr < h and 0 <= cc < w:
                    if grid[rr][cc] == background:
                        out[rr][cc] = color
                    rr += dr
                    cc += dc
    return out

